SELECT pg_temp.bassert((SELECT jsonb_array_length(value->'value') FROM jsonb_array_elements(public.benefits_rules_list()->'rules') WHERE value->>'rule_key'='checklist.smmc_ltc')=18,'default checklist not exposed');
